const event = $json.body.events[0];
const postbackData = JSON.parse(event.postback.data);

return {
  json: {
    replyToken: event.replyToken,
    userID: event.source.userId,
    action: postbackData.action,
    lineID: postbackData.lineID,
    leave_type: postbackData.leave_type,
    start_date: postbackData.start_date,
    end_date: postbackData.end_date,
    start_time: postbackData.start_time || '',
    end_time: postbackData.end_time || '',
    days: postbackData.days,
    reason: postbackData.reason
  }
};

const postback = $('Parse Postback Data').first().json;
const employee = $json;

const leaveType = postback.leave_type;
const days = parseFloat(postback.days);

// คำนวณยอดคงเหลือ
const currentBalance = leaveType === 'sick' 
  ? parseFloat(employee.sick_balance) 
  : parseFloat(employee.annual_balance);
const newBalance = currentBalance - days;

// ฟังก์ชันแปลงวันที่เป็น พ.ศ.
function formatThaiDate(dateString) {
  if (!dateString) return "";
  const parts = dateString.split('-');
  if (parts.length !== 3) return dateString;
  const yearBE = parseInt(parts[0]) + 543;
  return `${parts[2]}/${parts[1]}/${yearBE}`;
}

const leaveTypeThai = leaveType === 'sick' ? 'ลาป่วย' : 'ลากิจ/พักร้อน';
const startDateThai = formatThaiDate(postback.start_date);
const endDateThai = formatThaiDate(postback.end_date);

let dateRange = startDateThai;
if (postback.start_date !== postback.end_date) {
  dateRange = `${startDateThai} ถึง ${endDateThai}`;
}

return {
  json: {
    ...postback,
    employee_id: employee.employee_id,
    firstname: employee.firstname,
    lastname: employee.lastname,
    email: employee.email,
    current_balance: currentBalance,
    new_balance: newBalance,
    leaveTypeThai: leaveTypeThai,
    dateRange: dateRange,
    balance_field: leaveType === 'sick' ? 'sick_balance' : 'annual_balance'
  }
};

